// Button presses and replies to approval messages; long polling is not needed for one chat.
const token = $env.TELEGRAM_BOT_TOKEN;
const chat = String($env.TELEGRAM_CHAT_ID);
const state = $getWorkflowStaticData('global');
const api = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/${method}`, body, json: true, timeout: 15000 });
const dropButtons = (messageId) => api('editMessageReplyMarkup', { chat_id: chat, message_id: messageId, reply_markup: { inline_keyboard: [] } }).catch(() => {});

const updates = await api('getUpdates', { offset: state.offset || 0, timeout: 0, allowed_updates: ['message', 'callback_query'] });
const events = [];
for (const u of updates.result) {
  state.offset = u.update_id + 1;
  const cq = u.callback_query;
  if (cq && String(cq.message?.chat?.id) === chat) {
    const m = /^ap:(\d+):([ar])$/.exec(cq.data || '');
    await api('answerCallbackQuery', { callback_query_id: cq.id, text: m ? (m[2] === 'a' ? 'Одобрено' : 'Отклонено') : '' }).catch(() => {});
    if (m) {
      await dropButtons(cq.message.message_id);
      events.push({ json: { event: { type: 'decision', approval_id: Number(m[1]), decision: m[2] === 'a' ? 'approved' : 'rejected' } } });
    }
  }
  const msg = u.message;
  if (msg && String(msg.chat.id) === chat && msg.reply_to_message && msg.text) {
    await dropButtons(msg.reply_to_message.message_id);
    events.push({ json: { event: { type: 'reply', message_id: msg.reply_to_message.message_id, text: msg.text } } });
  }
}
return events;
